/**
 * Request-body schemas shared by the API (validation), the web app (forms) and future mobile clients.
 * Response shapes are documented in the OpenAPI spec generated by the API (/api/docs).
 */
import { z } from 'zod';
import {
  ANYDESK_ADDRESS_RE,
  CONTACT_METHODS,
  DEVICE_TYPES,
  FULFILMENT_METHODS,
  ORDER_STATUSES,
  PAYMENT_METHODS,
  PRODUCT_CONDITIONS,
  QUOTATION_ITEM_TYPES,
  REQUEST_STATUSES,
  SERVICE_TYPES,
  URGENCY_LEVELS,
  normalizeAnyDeskAddress,
} from './workflow.js';
import { ORG_ROLES, ROLES } from './rbac.js';

const trimmed = (max: number) => z.string().trim().min(1).max(max);
const optionalText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .optional()
    .transform((v) => (v === '' ? undefined : v));
const phone = z
  .string()
  .trim()
  .regex(/^\+?[0-9 ()-]{7,20}$/, 'Enter a valid telephone number');
const idParam = z.coerce.number().int().positive();

export const passwordSchema = z
  .string()
  .min(10, 'Use at least 10 characters')
  .max(128)
  .regex(/[A-Za-z]/, 'Include a letter')
  .regex(/[0-9]/, 'Include a number');

/* ---------------- auth & accounts ---------------- */

export const registerSchema = z
  .object({
    accountType: z.enum(['INDIVIDUAL', 'CORPORATE']),
    firstName: trimmed(80),
    lastName: trimmed(80),
    email: z.email().max(190).transform((e) => e.toLowerCase()),
    phone,
    password: passwordSchema,
    organizationName: optionalText(160),
    organizationRegistrationNo: optionalText(80),
    department: optionalText(120),
    acceptTerms: z.literal(true, { error: 'You must accept the terms of service' }),
  })
  .refine((v) => v.accountType === 'INDIVIDUAL' || !!v.organizationName, {
    path: ['organizationName'],
    message: 'Organisation name is required for corporate accounts',
  });
export type RegisterInput = z.infer<typeof registerSchema>;

export const loginSchema = z.object({
  email: z.email().transform((e) => e.toLowerCase()),
  password: z.string().min(1).max(128),
});
export const refreshSchema = z.object({ refreshToken: z.string().min(20).max(200).optional() });
export const forgotPasswordSchema = z.object({ email: z.email().transform((e) => e.toLowerCase()) });
export const resetPasswordSchema = z.object({ token: z.string().min(20).max(200), password: passwordSchema });
export const changePasswordSchema = z.object({ currentPassword: z.string().min(1), newPassword: passwordSchema });
export const acceptInviteSchema = z.object({
  token: z.string().min(20).max(200),
  password: passwordSchema,
  phone: phone.optional(),
});

export const updateProfileSchema = z.object({
  firstName: trimmed(80).optional(),
  lastName: trimmed(80).optional(),
  phone: phone.optional(),
});

export const addressSchema = z.object({
  label: trimmed(60),
  line1: trimmed(160),
  line2: optionalText(160),
  city: trimmed(80),
  region: optionalText(80),
  postalCode: optionalText(20),
  country: trimmed(80),
  phone: phone.optional(),
  isDefault: z.boolean().optional(),
});

/* ---------------- organisations ---------------- */

export const organizationUpdateSchema = z.object({
  name: trimmed(160).optional(),
  registrationNo: optionalText(80),
  billingEmail: z.email().optional(),
  phone: phone.optional(),
  address: optionalText(300),
  centralBilling: z.boolean().optional(),
});
export const inviteMemberSchema = z.object({
  email: z.email().transform((e) => e.toLowerCase()),
  firstName: trimmed(80),
  lastName: trimmed(80),
  orgRole: z.enum([ORG_ROLES.ORG_ADMIN, ORG_ROLES.ORG_MEMBER]).default('ORG_MEMBER'),
  department: optionalText(120),
  location: optionalText(120),
});
export const updateMemberSchema = z.object({
  orgRole: z.enum([ORG_ROLES.ORG_ADMIN, ORG_ROLES.ORG_MEMBER]).optional(),
  department: optionalText(120),
  location: optionalText(120),
  active: z.boolean().optional(),
});

/* ---------------- staff administration ---------------- */

export const createStaffSchema = z.object({
  email: z.email().transform((e) => e.toLowerCase()),
  firstName: trimmed(80),
  lastName: trimmed(80),
  phone: phone.optional(),
  roles: z
    .array(z.enum([ROLES.ADMIN, ROLES.SUPPORT_MANAGER, ROLES.TECHNICIAN, ROLES.INVENTORY_MANAGER, ROLES.FINANCE_OFFICER]))
    .min(1),
  specialties: optionalText(300),
});
export const updateUserRolesSchema = z.object({
  roles: z.array(z.enum(Object.values(ROLES) as [string, ...string[]])).min(1),
});
export const setUserActiveSchema = z.object({ active: z.boolean() });

/* ---------------- devices & support requests ---------------- */

export const deviceSchema = z.object({
  deviceType: z.enum(DEVICE_TYPES),
  manufacturer: optionalText(80),
  model: optionalText(120),
  operatingSystem: optionalText(80),
  serialNumber: optionalText(120),
  assetTag: optionalText(80),
  department: optionalText(120),
  location: optionalText(120),
  notes: optionalText(500),
});
export type DeviceInput = z.infer<typeof deviceSchema>;

export const createSupportRequestSchema = z
  .object({
    serviceType: z.enum(Object.values(SERVICE_TYPES) as [string, ...string[]]),
    categoryId: idParam,
    title: trimmed(160),
    description: z.string().trim().min(10, 'Please describe the problem in a little more detail').max(5000),
    errorMessages: optionalText(2000),
    urgency: z.enum(URGENCY_LEVELS).default('NORMAL'),
    preferredContact: z.enum(CONTACT_METHODS).default('EMAIL'),
    contactName: trimmed(160),
    contactEmail: z.email(),
    contactPhone: phone,
    department: optionalText(120),
    location: optionalText(160),
    /** existing device of the customer/organisation, or a new one described inline */
    deviceId: idParam.optional(),
    device: deviceSchema.optional(),
    /** on-site requests: where the visit should happen */
    siteAddress: optionalText(300),
    preferredVisitDate: z.iso.date().optional(),
  })
  .refine((v) => v.serviceType !== 'ONSITE_SUPPORT' || !!v.siteAddress, {
    path: ['siteAddress'],
    message: 'Tell us where the on-site visit should take place',
  })
  .refine((v) => v.serviceType !== 'HARDWARE_REPAIR' || !!v.deviceId || !!v.device, {
    path: ['device'],
    message: 'Hardware repairs need the device details',
  });
export type CreateSupportRequestInput = z.infer<typeof createSupportRequestSchema>;

export const listRequestsQuery = z.object({
  status: z.enum(REQUEST_STATUSES).optional(),
  statusGroup: z.enum(['open', 'active', 'closed', 'all']).optional(),
  serviceType: z.enum(Object.values(SERVICE_TYPES) as [string, ...string[]]).optional(),
  categoryId: idParam.optional(),
  technicianId: idParam.optional(),
  organizationId: idParam.optional(),
  urgency: z.enum(URGENCY_LEVELS).optional(),
  q: z.string().trim().max(100).optional(),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(20),
});

export const reviewRequestSchema = z.object({
  decision: z.enum(['ACCEPT', 'REQUEST_INFO', 'REJECT']),
  categoryId: idParam.optional(),
  serviceType: z.enum(Object.values(SERVICE_TYPES) as [string, ...string[]]).optional(),
  urgency: z.enum(URGENCY_LEVELS).optional(),
  message: optionalText(2000),
});
export const assignSchema = z.object({ technicianUserId: idParam, note: optionalText(500) });
export const changeStatusSchema = z.object({
  status: z.enum(REQUEST_STATUSES),
  note: optionalText(2000),
  visibleToCustomer: z.boolean().default(true),
});
export const progressUpdateSchema = z.object({ message: trimmed(2000), visibleToCustomer: z.boolean().default(true) });
export const messageSchema = z.object({ body: trimmed(5000) });
export const internalNoteSchema = z.object({ body: trimmed(5000) });
export const cancelRequestSchema = z.object({ reason: trimmed(1000) });

export const categorySchema = z.object({
  name: trimmed(120),
  description: optionalText(500),
  defaultServiceType: z.enum(Object.values(SERVICE_TYPES) as [string, ...string[]]).optional(),
  icon: optionalText(40),
  sortOrder: z.coerce.number().int().min(0).max(1000).default(100),
  active: z.boolean().default(true),
});

/* ---------------- remote support ---------------- */

export const requestRemoteSessionSchema = z.object({ instructions: optionalText(2000) });
export const authorizeRemoteSessionSchema = z.object({
  anydeskAddress: z
    .string()
    .trim()
    .max(80)
    .transform(normalizeAnyDeskAddress)
    .refine((v) => ANYDESK_ADDRESS_RE.test(v), {
      message: 'Enter the 9–10 digit AnyDesk ID (or your AnyDesk alias) shown in the AnyDesk window — never a password',
    }),
  consent: z.literal(true, { error: 'You must authorise the remote session to continue' }),
  consentVersion: trimmed(40),
});
export const remoteSessionStatusSchema = z.object({
  status: z.enum(['INITIATED', 'ACTIVE', 'CANCELLED']),
  note: optionalText(1000),
});
export const completeRemoteSessionSchema = z.object({
  outcome: z.enum(['RESOLVED', 'PARTIALLY_RESOLVED', 'NOT_RESOLVED', 'FOLLOW_UP_REQUIRED']),
  workPerformed: trimmed(5000),
  anydeskSessionId: optionalText(80),
  startedAt: z.iso.datetime({ offset: true }).optional(),
  endedAt: z.iso.datetime({ offset: true }).optional(),
});
export const revokeConsentSchema = z.object({ reason: optionalText(500) });

/* ---------------- repairs ---------------- */

export const intakeSchema = z.object({
  intakeType: z.enum(['WORKSHOP', 'ONSITE']),
  conditionNotes: trimmed(2000),
  accessories: optionalText(1000),
  serialNumber: optionalText(120),
  appointmentAt: z.iso.datetime({ offset: true }).optional(),
  customerAcknowledged: z.boolean(),
  acknowledgedByName: optionalText(160),
});
export const diagnosticSchema = z.object({
  findings: trimmed(5000),
  rootCause: optionalText(2000),
  recommendedAction: optionalText(2000),
  visibleToCustomer: z.boolean().default(true),
});
export const workLogSchema = z.object({
  activity: trimmed(5000),
  minutesSpent: z.coerce.number().int().min(0).max(24 * 60).default(0),
  visibleToCustomer: z.boolean().default(false),
});

export const quotationItemSchema = z
  .object({
    itemType: z.enum(QUOTATION_ITEM_TYPES),
    description: trimmed(300),
    productId: idParam.optional(),
    quantity: z.coerce.number().int().min(1).max(1000),
    unitPriceMinor: z.coerce.number().int().min(0).max(10_000_000_000),
  })
  .refine((v) => v.itemType !== 'PART' || !!v.productId, {
    path: ['productId'],
    message: 'Parts must be linked to a stocked product so they can be reserved',
  });
export const createQuotationSchema = z.object({
  items: z.array(quotationItemSchema).min(1).max(100),
  expectedDurationDays: z.coerce.number().int().min(0).max(365).optional(),
  validDays: z.coerce.number().int().min(1).max(180).default(14),
  notes: optionalText(2000),
  send: z.boolean().default(true),
});
export const quotationDecisionSchema = z.object({
  decision: z.enum(['APPROVE', 'DECLINE']),
  comment: optionalText(1000),
});

export const installPartSchema = z.object({ repairPartId: idParam });
export const serviceReportSchema = z.object({
  originalProblem: trimmed(5000),
  diagnosis: trimmed(5000),
  actionsPerformed: trimmed(5000),
  changesMade: optionalText(5000),
  testingResults: trimmed(5000),
  recommendations: optionalText(3000),
  warrantyDays: z.coerce.number().int().min(0).max(3650).default(0),
  warrantyTerms: optionalText(2000),
  outcome: z.enum(['RESOLVED', 'PARTIALLY_RESOLVED', 'NOT_RESOLVED', 'NOT_REPAIRABLE']),
});
export const feedbackSchema = z.object({
  rating: z.coerce.number().int().min(1).max(5),
  issueResolved: z.boolean(),
  timelinessRating: z.coerce.number().int().min(1).max(5).optional(),
  communicationRating: z.coerce.number().int().min(1).max(5).optional(),
  professionalismRating: z.coerce.number().int().min(1).max(5).optional(),
  comment: optionalText(3000),
});

/* ---------------- catalogue & inventory ---------------- */

export const productCategorySchema = z.object({
  name: trimmed(120),
  slug: z.string().trim().regex(/^[a-z0-9-]{2,80}$/).optional(),
  parentId: idParam.nullable().optional(),
  description: optionalText(500),
  sortOrder: z.coerce.number().int().min(0).max(1000).default(100),
  active: z.boolean().default(true),
});
export const productSchema = z.object({
  sku: z.string().trim().regex(/^[A-Za-z0-9._-]{2,60}$/, 'Letters, numbers, dot, dash or underscore'),
  name: trimmed(200),
  categoryId: idParam,
  description: z.string().trim().max(10000).default(''),
  priceMinor: z.coerce.number().int().min(0).max(10_000_000_000),
  condition: z.enum(PRODUCT_CONDITIONS).default('NEW'),
  brand: optionalText(80),
  warrantyMonths: z.coerce.number().int().min(0).max(120).default(0),
  warrantyInfo: optionalText(1000),
  compatibility: optionalText(2000),
  specifications: z.record(z.string().max(80), z.string().max(300)).default({}),
  reorderLevel: z.coerce.number().int().min(0).max(100000).default(2),
  isActive: z.boolean().default(true),
  isFeatured: z.boolean().default(false),
  isSparePart: z.boolean().default(false),
});
export const productListQuery = z.object({
  q: z.string().trim().max(100).optional(),
  categoryId: idParam.optional(),
  condition: z.enum(PRODUCT_CONDITIONS).optional(),
  minPriceMinor: z.coerce.number().int().min(0).optional(),
  maxPriceMinor: z.coerce.number().int().min(0).optional(),
  inStock: z.enum(['true', 'false']).optional(),
  featured: z.enum(['true', 'false']).optional(),
  sort: z.enum(['newest', 'price_asc', 'price_desc', 'name']).default('newest'),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(60).default(24),
});
export const stockAdjustmentSchema = z.object({
  productId: idParam,
  quantityDelta: z.coerce.number().int().refine((n) => n !== 0, 'Quantity change cannot be zero'),
  reason: trimmed(300),
});
export const supplierSchema = z.object({
  name: trimmed(160),
  contactName: optionalText(160),
  email: z.email().optional(),
  phone: phone.optional(),
  address: optionalText(300),
  notes: optionalText(1000),
  active: z.boolean().default(true),
});
export const purchaseOrderSchema = z.object({
  supplierId: idParam,
  expectedAt: z.iso.date().optional(),
  notes: optionalText(1000),
  items: z
    .array(
      z.object({
        productId: idParam,
        quantity: z.coerce.number().int().min(1).max(100000),
        unitCostMinor: z.coerce.number().int().min(0),
      }),
    )
    .min(1),
});
export const receivePurchaseOrderSchema = z.object({
  items: z.array(z.object({ purchaseOrderItemId: idParam, quantityReceived: z.coerce.number().int().min(1) })).min(1),
});

/* ---------------- cart, checkout, orders, payments ---------------- */

export const cartItemSchema = z.object({ productId: idParam, quantity: z.coerce.number().int().min(1).max(100) });
export const cartItemUpdateSchema = z.object({ quantity: z.coerce.number().int().min(0).max(100) });
export const checkoutSchema = z
  .object({
    fulfilmentMethod: z.enum(FULFILMENT_METHODS),
    addressId: idParam.optional(),
    paymentMethod: z.enum(PAYMENT_METHODS),
    customerNote: optionalText(1000),
  })
  .refine((v) => v.fulfilmentMethod !== 'DELIVERY' || !!v.addressId, {
    path: ['addressId'],
    message: 'Choose a delivery address',
  });
export const orderStatusSchema = z.object({ status: z.enum(ORDER_STATUSES), note: optionalText(1000) });
export const recordPaymentSchema = z.object({
  payableType: z.enum(['SALES_ORDER', 'SUPPORT_REQUEST']),
  payableId: idParam,
  method: z.enum(PAYMENT_METHODS).refine((m) => m !== 'GATEWAY', 'Gateway payments are recorded by the gateway'),
  amountMinor: z.coerce.number().int().positive(),
  reference: trimmed(120),
  note: optionalText(500),
});
export const refundPaymentSchema = z.object({ reason: trimmed(500) });
export const initiateRequestPaymentSchema = z.object({ method: z.enum(PAYMENT_METHODS) });

/* ---------------- settings ---------------- */

export const settingsUpdateSchema = z.object({
  businessName: trimmed(160).optional(),
  contactEmail: z.email().optional(),
  contactPhone: phone.optional(),
  contactAddress: optionalText(300),
  supportHours: optionalText(200),
  currencyCode: z.string().regex(/^[A-Z]{3}$/).optional(),
  currencyMinorDigits: z.coerce.number().int().min(0).max(3).optional(),
  taxRateBasisPoints: z.coerce.number().int().min(0).max(5000).optional(),
  taxLabel: optionalText(40),
  taxInclusive: z.boolean().optional(),
  deliveryFeeMinor: z.coerce.number().int().min(0).optional(),
  anydeskDownloadUrl: z.url().optional(),
  remoteConsentText: optionalText(5000),
  remoteConsentVersion: optionalText(40),
  intakeTermsText: optionalText(5000),
  termsOfServiceText: optionalText(20000),
  privacyNoticeText: optionalText(20000),
  quotationDefaultValidDays: z.coerce.number().int().min(1).max(180).optional(),
  enabledPaymentMethods: z.array(z.enum(PAYMENT_METHODS)).optional(),
  bankTransferInstructions: optionalText(2000),
  mobileMoneyInstructions: optionalText(2000),
});
export type SettingsUpdate = z.infer<typeof settingsUpdateSchema>;

export const reportRangeQuery = z.object({
  from: z.iso.date().optional(),
  to: z.iso.date().optional(),
  format: z.enum(['json', 'csv']).default('json'),
});
export const idParamSchema = z.object({ id: idParam });
